/**
 * CODEZ48 COMMAND POLICY & SANDBOX
 * Validates commands generated by adapters to prevent dangerous shell execution.
 */

class CommandPolicy {
    constructor() {
        // Allowed command prefixes for developer workflows
        this.allowedPrefixes = [
            'npm ', 'npx ', 'pnpm ', 'yarn ',
            'node ', 'nodenv ',
            'python ', 'python3 ', 'pip ', 'pip3 ', 'venv ',
            'java ', 'javac ', 'mvn ', 'gradle ', 'gradlew ', './gradlew ', 'gradlew.bat ',
            'dotnet ',
            'flutter ', 'dart ',
            'adb ',
            'code '
        ];

        // Forbidden commands/tokens
        this.blockedTokens = [
            'rm -rf /', 'rmdir /s /q c:', 'format', 'mkfs',
            'drop database', 'delete from', 'shutdown', 'reboot',
            'curl | sh', 'wget | sh', 'bash -i', 'nc -e',
            'icacls', 'takeown', 'net user', 'reg add'
        ];
    }

    validate(command, projectPath) {
        if (!command || typeof command !== 'string') {
            return { allowed: false, reason: 'Empty or invalid command.' };
        }

        const trimmed = command.trim().toLowerCase();

        // Check blocked tokens
        for (const token of this.blockedTokens) {
            if (trimmed.includes(token)) {
                return { allowed: false, reason: `Command contains dangerous pattern: '${token}'` };
            }
        }

        // Check if command starts with an allowed adapter prefix
        const isAllowed = this.allowedPrefixes.some(prefix => trimmed.startsWith(prefix.trim()));
        if (!isAllowed) {
            return { allowed: false, reason: `Command '${command}' is not in the trusted developer allowlist.` };
        }

        return { allowed: true };
    }
}

module.exports = new CommandPolicy();
